from typing import Tuple

def leg_witness(n: int) -> Tuple[int, int]:
    """Explicit companion (b, c) with n^2 + b^2 = c^2 for n >= 3."""
    if n < 3:
        raise ValueError("1 and 2 are not legs")
    if n % 2 == 0:
        k = n // 2
        return (k * k - 1, k * k + 1)
    k = (n - 1) // 2
    b = 2 * k * k + 2 * k
    return (b, b + 1)

for n in range(3, 15):
    b, c = leg_witness(n)
    assert n * n + b * b == c * c
    print(f"{n}^2 + {b}^2 = {c}^2")

from typing import Tuple, Dict

def triple_laws(a: int, b: int, c: int) -> Dict[str, bool]:
    """Check universal divisibility laws for a Pythagorean triple."""
    assert a * a + b * b == c * c
    ab, abc = a * b, a * b * c
    return {
        "3|ab": ab % 3 == 0, "4|ab": ab % 4 == 0, "12|ab": ab % 12 == 0,
        "6|area": (ab // 2) % 6 == 0, "5|abc": abc % 5 == 0, "60|abc": abc % 60 == 0,
    }

def parametrize(m: int, n: int) -> Tuple[int, int, int]:
    return (m * m - n * n, 2 * m * n, m * m + n * n)

ok = all(all(triple_laws(*parametrize(m, n)).values())
         for m in range(2, 40) for n in range(1, m))
print("All divisibility laws hold for every parametrized triple up to m=40:", ok)

from typing import Tuple, Dict

def quadruple_laws(a: int, b: int, c: int, d: int) -> Dict[str, bool]:
    """Verify parity rigidity of a Pythagorean quadruple a^2+b^2+c^2=d^2."""
    assert a * a + b * b + c * c == d * d
    num_even = sum(1 for x in (a, b, c) if x % 2 == 0)
    return {"at least two even": num_even >= 2, "4|abc": (a * b * c) % 4 == 0}

# Enumerate small quadruples and confirm the parity law never fails.
found = []
for d in range(1, 40):
    for a in range(1, d):
        for b in range(a, d):
            c2 = d * d - a * a - b * b
            c = int(round(c2 ** 0.5))
            if c >= b and c * c == c2 and c > 0:
                found.append((a, b, c, d))
assert all(quadruple_laws(*q)["at least two even"] for q in found)
assert all(quadruple_laws(*q)["4|abc"] for q in found)
print(f"Checked {len(found)} quadruples; all obey 'at most one odd edge' and 4|abc.")

