    return (k*k - 1, k*k + 1)      # c - b = 2
  else:
    k <- (n - 1) / 2
    b <- 2*k*k + 2*k
    return (b, b + 1)              # c - b = 1

function CERTIFY(modulus m, arity k, equation E, conclusion C):
  for each tuple t in (Z/mZ)^k:
    if E(t) is true and C(t) is false:
      return FALSE
  return TRUE

function ENUMERATE_TRIPLES(bound):
  for m from 2 to bound:
    for n from 1 to m-1:
      a <- m*m - n*n
      b <- 2*m*n
      c <- m*m + n*n
      emit (a, b, c)

